  const wrap = h('span', { style: { position: 'relative', display: 'inline-flex' } }, children, tip);
  let t;
  const show = () => { clearTimeout(t); t = setTimeout(() => tip.dataset.open = 'true', 180); };
  const hide = () => { clearTimeout(t); tip.dataset.open = 'false'; };
